<?php
namespace App\Services\HR;
use App\Models\AttendanceDevice;
use App\Models\AttendanceDeviceSyncLog;
use Carbon\Carbon;
use Illuminate\Support\Facades\DB;
class AttendanceDeviceSyncService { public function sync(AttendanceDevice $device,Carbon $from,Carbon $to,?int $actorId=null,string $type='manual'): AttendanceDeviceSyncLog { if($to->lt($from) || $from->diffInDays($to)>31) throw new \InvalidArgumentException('Sync range must be valid and no longer than 31 days.'); $running=AttendanceDeviceSyncLog::where('device_id',$device->id)->where('status','running')->exists(); if($running) throw new \RuntimeException('A sync is already running for this device.'); $log=AttendanceDeviceSyncLog::create(['device_id'=>$device->id,'sync_type'=>$type,'started_at'=>now(),'from_datetime'=>$from,'to_datetime'=>$to,'initiated_by'=>$actorId]); $fetched=$inserted=$duplicates=$failed=$processed=0; try { foreach(app(AttendanceDeviceAdapterManager::class)->adapter($device)->fetchLogs($device,$from,$to) as $payload){$fetched++;$row=app(AttendanceDeviceLogService::class)->ingest($device,(array)$payload);$row->is_duplicate?$duplicates++:$inserted++;if(!$row->is_duplicate){app(\App\Jobs\ProcessAttendanceDeviceLogJob::class)::dispatch($row->id,$actorId);$processed++;}} $log->update(['completed_at'=>now(),'records_fetched'=>$fetched,'records_inserted'=>$inserted,'records_duplicate'=>$duplicates,'records_failed'=>$failed,'records_processed'=>$processed,'status'=>$failed?'partial':'completed']);$device->update(['last_sync_at'=>now(),'last_successful_sync_at'=>now()]); } catch(\Throwable $e) {$log->update(['completed_at'=>now(),'records_fetched'=>$fetched,'records_inserted'=>$inserted,'records_duplicate'=>$duplicates,'records_failed'=>$failed+1,'status'=>'failed','error_message'=>'Device sync failed.']);$device->update(['last_sync_at'=>now()]);throw $e;} return $log; } }
